<?php
declare(strict_types=1);
namespace LifeOS\Core;
use PDO;
final class BackgroundJobQueue {
 public function __construct(private readonly PDO $pdo) {}
 public function enqueue(string $type,array $payload,?string $availableAt=null,int $maxAttempts=5): int {if(!preg_match('/^[a-z][a-z0-9_.-]{1,79}$/',$type))throw new \InvalidArgumentException('Job type tidak valid.');$q=$this->pdo->prepare("INSERT INTO background_jobs(job_type,payload,status,available_at,max_attempts,created_at) VALUES(:t,:p,'pending',COALESCE(:a,UTC_TIMESTAMP()),:m,UTC_TIMESTAMP())");$q->execute(['t'=>$type,'p'=>json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),'a'=>$availableAt,'m'=>max(1,min(20,$maxAttempts))]);return (int)$this->pdo->lastInsertId();}
 public function claim(int $limit=10,int $lease=300): array {$limit=max(1,min(50,$limit));$lease=max(30,min(3600,$lease));$token=bin2hex(random_bytes(16));return Database::transaction(function(PDO $pdo)use($limit,$lease,$token){$ids=array_map('intval',$pdo->query("SELECT id FROM background_jobs WHERE status='pending' AND available_at<=UTC_TIMESTAMP() ORDER BY available_at,id LIMIT {$limit} FOR UPDATE")->fetchAll(PDO::FETCH_COLUMN));if(!$ids)return [];$marks=implode(',',array_fill(0,count($ids),'?'));$u=$pdo->prepare("UPDATE background_jobs SET status='processing',claim_token=?,claimed_until=DATE_ADD(UTC_TIMESTAMP(),INTERVAL {$lease} SECOND),attempts=attempts+1 WHERE status='pending' AND id IN ({$marks})");$u->execute(array_merge([$token],$ids));$s=$pdo->prepare("SELECT id,job_type,payload,attempts,max_attempts,claim_token FROM background_jobs WHERE status='processing' AND claim_token=?");$s->execute([$token]);return $s->fetchAll(PDO::FETCH_ASSOC);});}
 public function complete(int $id,string $token): void {$q=$this->pdo->prepare("UPDATE background_jobs SET status='completed',completed_at=UTC_TIMESTAMP(),claim_token=NULL,claimed_until=NULL WHERE id=:id AND status='processing' AND claim_token=:t");$q->execute(['id'=>$id,'t'=>$token]);}
 public function fail(int $id,string $token,string $code): void {$q=$this->pdo->prepare("UPDATE background_jobs SET status=IF(attempts>=max_attempts,'failed','pending'),last_error_code=:e,claim_token=NULL,claimed_until=NULL,available_at=DATE_ADD(UTC_TIMESTAMP(),INTERVAL LEAST(attempts*30,1800) SECOND) WHERE id=:id AND status='processing' AND claim_token=:t");$q->execute(['e'=>substr($code,0,80),'id'=>$id,'t'=>$token]);}
 public function recoverExpired(): int {return $this->pdo->exec("UPDATE background_jobs SET status=IF(attempts>=max_attempts,'failed','pending'),claim_token=NULL,claimed_until=NULL,last_error_code='CLAIM_EXPIRED' WHERE status='processing' AND claimed_until<UTC_TIMESTAMP()");}
}
